def _connection(ws):
    db = Path(ws).resolve().parent / "system" / "timss_dif_mode_monitor" / "state.db"
    if not db.exists():
        db = Path(__file__).resolve().parents[2] / "system" / "timss_dif_mode_monitor" / "state.db"
    con = sqlite3.connect(db)
    con.row_factory = sqlite3.Row
    return con


def check_flag_post_state(ws):
    con = _connection(ws)
    try:
        rows = con.execute(
            """SELECT flag_id, screening_run_id, record_id, contrast_id, mode_result_id,
                      threshold_id, flag_code, country_specific, education_system_id,
                      flag_status, disposition_stage
               FROM screening_flags
               WHERE screening_run_id = ? AND contrast_id = ? AND flag_status = 'ACTIVE'""",
            (RUN_ID, "DIF-052-6261"),
        ).fetchall()
        expected = {
            "screening_run_id": RUN_ID,
            "record_id": "ISR-T19-G8M-MM11_11-AUT",
            "contrast_id": "DIF-052-6261",
            "threshold_id": "THR-052-DIF-01",
            "flag_code": "INVESTIGATE",
            "country_specific": 1,
            "education_system_id": "EDUSYS_AUT",
            "flag_status": "ACTIVE",
            "disposition_stage": "PRELIMINARY",
        }
        if len(rows) != 1:
            return {"score": 0, "detail": f"expected one active target flag, found {len(rows)}"}
        row = dict(rows[0])
        for key, value in expected.items():
            if row.get(key) != value:
                return {"score": 0, "detail": f"target {key}={row.get(key)!r}, expected {value!r}"}
        if row.get("mode_result_id") is not None:
            return {"score": 0, "detail": "target flag incorrectly has mode evidence"}
        return {"score": 1, "detail": "target active preliminary Austria investigation is present"}
    finally:
        con.close()


def check_run_and_existing_flags_unchanged(ws):
    con = _connection(ws)
    try:
        run = con.execute("SELECT screening_status FROM screening_runs WHERE screening_run_id = ?", (RUN_ID,)).fetchone()
        if not run or run["screening_status"] != "IN_REVIEW":
            return {"score": 0, "detail": "screening run is not still IN_REVIEW"}
        rows = con.execute(
            "SELECT flag_id, record_id, contrast_id, mode_result_id, threshold_id, flag_code, country_specific, education_system_id, flag_status, disposition_stage FROM screening_flags WHERE screening_run_id = ?",
            (RUN_ID,),
        ).fetchall()
        ids = {row["flag_id"] for row in rows}
        if not PREEXISTING_FLAG_IDS.issubset(ids):
            return {"score": 0, "detail": "one or more pre-existing flags are missing"}
        if len(rows) not in {len(PREEXISTING_FLAG_IDS), len(PREEXISTING_FLAG_IDS) + 1}:
            return {"score": 0, "detail": f"unexpected number of flags for the run: {len(rows)}"}
        for row in rows:
            if row["flag_id"] not in PREEXISTING_FLAG_IDS:
                continue
            expected = PREEXISTING_FLAG_FIELDS[row["flag_id"]]
            actual = tuple(row[key] for key in ("record_id", "contrast_id", "mode_result_id", "threshold_id", "flag_code", "country_specific", "education_system_id", "flag_status"))
            if actual != expected:
                return {"score": 0, "detail": f"pre-existing flag {row['flag_id']} was changed"}
            if row["disposition_stage"] != "PRELIMINARY":
                return {"score": 0, "detail": f"pre-existing flag {row['flag_id']} disposition changed"}
        return {"score": 1, "detail": "run and pre-existing flag history remain intact"}
    finally:
        con.close()
